-- Purpose: Add node group management tables with multi-group support
-- Author: Tension
-- Date: 2025-02-23
-- Updated: 2025-03-06

-- ===== Create node_group table =====
DROP TABLE IF EXISTS "node_group";
CREATE TABLE IF NOT EXISTS "node_group" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "name" varchar(255) NOT NULL DEFAULT '',
    "description" varchar(500) DEFAULT NULL,
    "sort" INTEGER NOT NULL DEFAULT 0,
    "for_calculation" BOOLEAN NOT NULL DEFAULT true,
    "min_traffic_gb" bigint DEFAULT 0,
    "max_traffic_gb" bigint DEFAULT 0,
    "created_at" TIMESTAMP(3) DEFAULT NULL,
    "updated_at" TIMESTAMP(3) DEFAULT NULL,
    PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "idx_node_group_sort" ON "node_group" ("sort");

-- ===== Create group_history table =====
DROP TABLE IF EXISTS "group_history";
CREATE TABLE IF NOT EXISTS "group_history" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "group_mode" varchar(50) NOT NULL DEFAULT '',
    "trigger_type" varchar(50) NOT NULL DEFAULT '',
    "state" varchar(50) NOT NULL DEFAULT '',
    "total_users" INTEGER NOT NULL DEFAULT 0,
    "success_count" INTEGER NOT NULL DEFAULT 0,
    "failed_count" INTEGER NOT NULL DEFAULT 0,
    "start_time" TIMESTAMP(3) DEFAULT NULL,
    "end_time" TIMESTAMP(3) DEFAULT NULL,
    "operator" varchar(100) DEFAULT NULL,
    "error_message" text DEFAULT NULL,
    "created_at" TIMESTAMP(3) DEFAULT NULL,
    PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "idx_group_history_group_mode" ON "group_history" ("group_mode");
CREATE INDEX IF NOT EXISTS "idx_group_history_trigger_type" ON "group_history" ("trigger_type");
CREATE INDEX IF NOT EXISTS "idx_group_history_state" ON "group_history" ("state");
CREATE INDEX IF NOT EXISTS "idx_group_history_created_at" ON "group_history" ("created_at");

-- ===== Create group_history_detail table =====
DROP TABLE IF EXISTS "group_history_detail";
CREATE TABLE IF NOT EXISTS "group_history_detail" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "history_id" bigint NOT NULL,
    "node_group_id" bigint NOT NULL,
    "user_count" INTEGER NOT NULL DEFAULT 0,
    "node_count" INTEGER NOT NULL DEFAULT 0,
    "user_data" TEXT DEFAULT NULL,
    "created_at" TIMESTAMP(3) DEFAULT NULL,
    PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "idx_group_history_detail_history_id" ON "group_history_detail" ("history_id");
CREATE INDEX IF NOT EXISTS "idx_group_history_detail_node_group_id" ON "group_history_detail" ("node_group_id");

-- ===== Add columns to nodes table =====
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'nodes' AND column_name = 'node_group_ids') THEN
        ALTER TABLE "nodes" ADD COLUMN "node_group_ids" JSONB DEFAULT NULL;
    END IF;
END $$;

-- ===== Add node_group_id column to user_subscribe table =====
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'user_subscribe' AND column_name = 'node_group_id') THEN
        ALTER TABLE "user_subscribe" ADD COLUMN "node_group_id" bigint NOT NULL DEFAULT 0;
    END IF;
END $$;

-- ===== Add index for user_subscribe.node_group_id =====
CREATE INDEX IF NOT EXISTS "idx_user_subscribe_node_group_id" ON "user_subscribe" ("node_group_id");

-- ===== Add group_locked column to user_subscribe table =====
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'user_subscribe' AND column_name = 'group_locked') THEN
        ALTER TABLE "user_subscribe" ADD COLUMN "group_locked" BOOLEAN NOT NULL DEFAULT false;
    END IF;
END $$;

-- ===== Add columns to subscribe table =====
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'subscribe' AND column_name = 'node_group_ids') THEN
        ALTER TABLE "subscribe" ADD COLUMN "node_group_ids" JSONB DEFAULT NULL;
    END IF;
END $$;

-- ===== Add default node_group_id column to subscribe table =====
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'subscribe' AND column_name = 'node_group_id') THEN
        ALTER TABLE "subscribe" ADD COLUMN "node_group_id" bigint NOT NULL DEFAULT 0;
    END IF;
END $$;

-- ===== Add index for subscribe.node_group_id =====
CREATE INDEX IF NOT EXISTS "idx_subscribe_node_group_id" ON "subscribe" ("node_group_id");

-- ===== Insert system configuration entries =====
INSERT INTO "system" ("category", "key", "value", "desc") VALUES
    ('group', 'enabled', 'false', 'Group Management Enabled'),
    ('group', 'mode', 'average', 'Group Mode: average/subscribe/traffic'),
    ('group', 'auto_create_group', 'false', 'Auto-create user group when creating subscribe product')
